import{_ as o,o as t,c as a,a3 as d}from"./chunks/framework.TWmUP5Ea.js";const p=JSON.parse('{"title":"Files & formats","description":"","frontmatter":{},"headers":[],"relativePath":"guide/files.md","filePath":"guide/files.md"}'),n={name:"guide/files.md"};function s(r,e,i,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="files-formats" tabindex="-1">Files &amp; formats <a class="header-anchor" href="#files-formats" aria-label="Permalink to &quot;Files &amp; formats&quot;">​</a></h1><p>Your writing lives in plain markdown files that any editor can read, today and in twenty years. When a piece goes out into the world, Blank hands it over as a finely typeset PDF or as a Word document. And when someone sends you a Word document, Blank opens that too.</p><h2 id="formats" tabindex="-1">Which format for what <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Which format for what {#formats}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Open</th><th>Save or export</th><th>Best for</th></tr></thead><tbody><tr><td>Markdown (.md)</td><td><code>Mod</code> <code>O</code></td><td><code>Mod</code> <code>S</code></td><td>your own writing</td></tr><tr><td>PDF</td><td></td><td><code>Mod</code> <code>Alt</code> <code>P</code></td><td>reading and printing</td></tr><tr><td>Word (.docx)</td><td><code>Mod</code> <code>O</code></td><td><code>Mod</code> <code>Alt</code> <code>W</code></td><td>people who use Word</td></tr></tbody></table><p><code>Mod</code> is <code>Cmd</code> on macOS and <code>Ctrl</code> on Windows and Linux.</p><h2 id="markdown" tabindex="-1">Your documents: markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Your documents: markdown {#markdown}&quot;">​</a></h2><p>Everything you write is kept as markdown: plain text with a few marks like <code>#</code> for headings, so the file stays small, readable and yours.</p><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>New file</td><td><code>Mod</code> <code>N</code></td></tr><tr><td>Open</td><td><code>Mod</code> <code>O</code></td></tr><tr><td>Save</td><td><code>Mod</code> <code>S</code></td></tr><tr><td>Save as</td><td><code>Mod</code> <code>Shift</code> <code>S</code></td></tr></tbody></table><p>The open dialog shows your markdown files and Word documents together. Closed Blank without saving? It keeps your text anyway, see <a href="./writing#blank-remembers-your-document">Blank remembers your document</a>.</p><h2 id="pdf" tabindex="-1">Share a PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;Share a PDF {#pdf}&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>P</code> and choose where to put the PDF. Blank suggests your document&#39;s name with <code>.pdf</code>.</p><p>The PDF is typeset with care, in the same font, sizes and spacing as the editor:</p><ul><li>A4 pages set in IBM Plex Sans,</li><li>a heading never ends a page on its own; it moves to the next page with its text,</li><li>quotes keep their bar on the left and everything inside them,</li><li>line breaks you made with <code>Shift</code> <code>Enter</code> stay, and a numbered list that starts at 3 starts at 3,</li><li>links stay clickable.</li></ul><p>Images come along at the size they have in Blank, up to the width of the page. Images from the web are downloaded for the PDF, so that needs an internet connection. If an image can&#39;t be loaded, the PDF shows its description in its place, and Blank tells you which one it was.</p><h2 id="word" tabindex="-1">Word documents <a class="header-anchor" href="#word" aria-label="Permalink to &quot;Word documents {#word}&quot;">​</a></h2><h3 id="send-word" tabindex="-1">Send a Word document <a class="header-anchor" href="#send-word" aria-label="Permalink to &quot;Send a Word document {#send-word}&quot;">​</a></h3><p>When someone needs your text in Word, press <code>Mod</code> <code>Alt</code> <code>W</code>. Blank suggests your document&#39;s name with <code>.docx</code>.</p><p>The Word document looks like your PDF, and stays easy to edit: headings, quotes and code use real Word styles, so they show up in Word&#39;s style gallery, navigation pane and table of contents. Lists keep their numbers, and links and images come along. Blank&#39;s font is embedded, so Word shows it even on computers that don&#39;t have it installed. LibreOffice and Google Docs use a similar font instead.</p><p>Your markdown file stays exactly as it is.</p><h3 id="open-word-documents" tabindex="-1">Open a Word document <a class="header-anchor" href="#open-word-documents" aria-label="Permalink to &quot;Open a Word document {#open-word-documents}&quot;">​</a></h3><p>Open a Word document like any other file: with <code>Mod</code> <code>O</code>, by starting Blank with it (<code>blank report.docx</code>), or with <strong>Open With → Blank</strong> in your file manager (see <a href="./install">Install</a>). Blank also opens .docm, .dotx and .dotm files, up to 50 MB.</p><p>Blank turns the document into a new, untitled markdown document, and the top of the window shows <em>report.docx (imported)</em>. Press <code>Mod</code> <code>S</code> to keep it: Blank suggests <code>report.md</code>, right next to the original.</p><div class="tip custom-block"><p class="custom-block-title">Your Word file stays untouched</p><p>Blank never writes to the Word document you opened. It won&#39;t even save markdown over a .docx or .pdf if you pick one in the save dialog.</p></div><h3 id="what-comes-along" tabindex="-1">What comes along <a class="header-anchor" href="#what-comes-along" aria-label="Permalink to &quot;What comes along {#what-comes-along}&quot;">​</a></h3><p>Headings, bold and italic text, links, lists, quotes, code, line breaks and images make it into your document. Images are stored inside the markdown file, so it stays a single file you can move and send; large pictures are scaled down to a size that still prints well.</p><p>Word can do more than markdown, so a few things change on the way:</p><ul><li>tables become one line per row, with the cells separated by <code>|</code>,</li><li>footnotes move to the end of the document,</li><li>comments, headers and footers, underlining and colours are left out,</li><li>tracked changes count as accepted,</li><li>charts and drawings Blank can&#39;t show are replaced by their description,</li><li>numbered lists start at 1.</li></ul><div class="tip custom-block"><p class="custom-block-title">Nothing gets lost unnoticed</p><p>Right after opening, Blank tells you what changed, for example <em>1 table became text</em> or <em>2 comments left out</em>.</p></div><h3 id="back-and-forth" tabindex="-1">Back and forth with Word users <a class="header-anchor" href="#back-and-forth" aria-label="Permalink to &quot;Back and forth with Word users {#back-and-forth}&quot;">​</a></h3><p>A colleague sends you a Word document to work on:</p><ol><li>Open it with <code>Mod</code> <code>O</code>.</li><li>Write, and keep your version with <code>Mod</code> <code>S</code>, as markdown.</li><li>Send it back with <code>Mod</code> <code>Alt</code> <code>W</code>.</li></ol><p>On their side, headings, quotes, lists, links and images arrive as they know them from Word. Tables come back as text, one line per row.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know {#good-to-know}&quot;">​</a></h2><p><strong>File names.</strong> On Linux, the save dialog doesn&#39;t add the extension for you. The name Blank suggests already has it, and an export refuses a name with another extension, such as an existing <code>.md</code> file, instead of overwriting it.</p><p><strong>Other formats.</strong> Blank can&#39;t open .doc, .odt, .rtf or .pages files. Save them as .docx in the app they come from, then open that.</p><p><strong>Password-protected documents.</strong> Blank can&#39;t open a Word document that is protected with a password. Remove the password in Word, or ask for an unprotected copy.</p>',36)])])}const u=o(n,[["render",s]]);export{p as __pageData,u as default};
